              data?.ready === true ||
              String(data?.status || '').toLowerCase() === 'ready' ||
              String(data || '').toLowerCase() === 'ok'
            )
          setIsHealthy(ok)
        } catch {
          setIsHealthy(healthRes.value.status === 200)
        }
      } else {
        setIsHealthy(null)
      }

      if (featuresRes.status === 'fulfilled') {
        setFeatures(featuresRes.value.data)
        console.info('[FF/UI] features:', featuresRes.value.data.length)
      } else {
        console.error('Dashboard: features fetch failed', featuresRes.reason)
      }

      if (runsRes.status === 'fulfilled') {
        setRuns(runsRes.value.data)
        console.info('[FF/UI] runs:', runsRes.value.data.length)
      } else {
        console.warn('Dashboard: runs fetch failed', runsRes.reason)
      }

      if (tokensRes.status === 'fulfilled') {
        setTokensSummary(tokensRes.value.data)
      } else {
        console.warn('Dashboard: tokens summary fetch failed (non-blocking)', tokensRes.reason)
        setTokensSummary(null)
      }

      if (errorsRes.status === 'fulfilled') {
        setCriticalErrors(errorsRes.value.data || [])
      } else {
        console.warn('Dashboard: errors fetch failed (non-blocking)', errorsRes.reason)
        setCriticalErrors([])
      }

      // Ошибкой считаем только падение базовых источников для вёрстки
