// Форматирование даты в локальный формат
export const formatDate = (dateString: string): string => {
  try {
    if (!dateString || dateString === '') {
      return 'Не указано'
    }

    const date = new Date(dateString)

    // Проверяем что дата валидна
    if (isNaN(date.getTime())) {
      return 'Invalid Date'
    }

    return date.toLocaleString('ru-RU', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
      timeZone: 'Europe/Moscow'
    })
  } catch (error) {
    console.error('Error formatting date:', error, 'for dateString:', dateString)
    return dateString || 'Ошибка даты'
  }
}

// Форматирование даты в относительный формат (например, "2 часа назад")
export const formatRelativeDate = (dateString: string): string => {
  try {
    if (!dateString || dateString === '') {
      return 'Неизвестно'
    }

    const date = new Date(dateString)

    // Проверяем что дата валидна
    if (isNaN(date.getTime())) {
      return 'Invalid Date'
    }

    const now = new Date()
    const diffMs = now.getTime() - date.getTime()
    const diffSecs = Math.floor(diffMs / 1000)
    const diffMins = Math.floor(diffSecs / 60)
    const diffHours = Math.floor(diffMins / 60)
    const diffDays = Math.floor(diffHours / 24)

    if (diffSecs < 60) {
      return `${diffSecs} сек. назад`
    } else if (diffMins < 60) {
      return `${diffMins} мин. назад`
    } else if (diffHours < 24) {
      return `${diffHours} ч. назад`
    } else if (diffDays < 30) {
      return `${diffDays} дн. назад`
    } else {
      return formatDate(dateString)
    }
  } catch (error) {
    console.error('Error formatting relative date:', error, 'for dateString:', dateString)
    return dateString || 'Ошибка даты'
  }
}

